-- StarterGui.ScreenGui.Frame.encryptButton.encryption
local function C_4()
	local frm = game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui").ScreenGui.Frame
	local chars = {}
	frm.TextBox:GetPropertyChangedSignal("Text"):Connect(function()
		text = frm.TextBox.Text
	end)
	frm.encryptButton.Activated:Connect(function()
		for i=1, string.len(text), 1 do
			local byte = string.byte(text, i)
			byte = byte + 5
			local char = string.char(byte)
			table.insert(chars, char)
		end
		local str = table.concat(chars, "", 1, #chars)
		setclipboard(str)
		frm.encryptButton.Text = "copied to clipboard"
		task.wait(2)
		frm.encryptButton.Text = "encrypt"
		table.clear(chars)
	end)
end
task.spawn(C_4);

-- decryption code --
for i,v in pairs(game:FindService("Players"):GetPlayers()) do
	v.Chatted:Connect(function(msg)
		local chars = {}
		for i=1, string.len(msg), 1 do
			if string.sub(msg, i, i) == "\n" or string.sub(msg, i, i) == "\b" then
				return
			end
			local byte = string.byte(msg, i)
			byte = byte - 5
			local char = string.char(byte)
			table.insert(chars, char)
		end
		local str = table.concat(chars, "", 1, #chars)
		table.clear(chars)
		print("[DECRYPTOR] "..v.Name..": "..str)
	end)
end
